CREATE FUNCTION public.test_assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Assertion failed: %',msg; END IF; END $$;
INSERT INTO auth.users VALUES('10000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
SET ROLE authenticated;
SELECT test_assert(jsonb_array_length(get_user_achievements()->'achievements')=24,'all 24 catalog entries');
SELECT test_assert(get_user_achievements()->'newly_unlocked_ids'='[]','empty initial backfill');
DO $$ BEGIN
 BEGIN PERFORM record_achievement_activity('experience-500'); RAISE EXCEPTION 'Accepted achievement ID'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 BEGIN PERFORM record_achievement_activity('mcp_tool_success'); RAISE EXCEPTION 'Accepted forged MCP success'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 BEGIN PERFORM record_achievement_service_activity('10000000-0000-0000-0000-000000000001','mcp_tool_success'); RAISE EXCEPTION 'Allowed service RPC'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN INSERT INTO user_achievement_awards(user_id,achievement_id,is_backfilled,qualifying_value) VALUES(auth.uid(),'experience-500',false,500); RAISE EXCEPTION 'Allowed grant'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM _refresh_user_achievements(auth.uid(),false); RAISE EXCEPTION 'Allowed internal evaluator'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
RESET ROLE;
INSERT INTO avatar_profiles VALUES('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',false),('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001',false),('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002',true);
INSERT INTO avatar_performance_cache(avatar_id,total_picks,wins,losses,best_streak) VALUES('20000000-0000-0000-0000-000000000001',6,3,3,2),('20000000-0000-0000-0000-000000000002',6,3,3,2);
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='experience-10'),'two agents 6+6 never combine');
UPDATE avatar_performance_cache SET total_picks=10,wins=6,losses=4,best_streak=3 WHERE avatar_id='20000000-0000-0000-0000-000000000001';
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='experience-10' AND credited_agent_id='20000000-0000-0000-0000-000000000001'),'exact experience threshold and attribution');
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='streak-3'),'streak threshold');
UPDATE avatar_performance_cache SET total_picks=110,wins=54,losses=45,net_units=9.99 WHERE avatar_id='20000000-0000-0000-0000-000000000001';
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='consistent'),'pushes do not fill 100 decided requirement');
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='plus-10-units'),'units threshold strict');
UPDATE avatar_performance_cache SET wins=55,losses=45,net_units=25,best_streak=15 WHERE avatar_id='20000000-0000-0000-0000-000000000001';
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='consistent'),'exact 55 percent of100');
SELECT test_assert((SELECT count(*) FROM user_achievement_awards WHERE achievement_id IN ('plus-10-units','plus-25-units','streak-3','streak-5','streak-10','streak-15'))=6,'all crossed thresholds');
CREATE TEMP TABLE earned_snapshot AS SELECT achievement_id,earned_at FROM user_achievement_awards WHERE user_id='10000000-0000-0000-0000-000000000001';
UPDATE avatar_performance_cache SET total_picks=0,wins=0,losses=0,net_units=-10,best_streak=0 WHERE avatar_id='20000000-0000-0000-0000-000000000001';
SELECT test_assert(NOT EXISTS(SELECT 1 FROM earned_snapshot s LEFT JOIN user_achievement_awards a USING(achievement_id,earned_at) WHERE a.achievement_id IS NULL),'decline never changes earned timestamp');
INSERT INTO avatar_parlays VALUES('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001');
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='first-picks'),'parlay generation counts first picks');
INSERT INTO user_avatar_follows VALUES('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000002');
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='first-follow'),'self-follow does not qualify');
INSERT INTO user_avatar_follows VALUES('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000003');
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='first-follow'),'follow another public agent');
INSERT INTO nfl_analysis_saved_filters VALUES('40000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',NULL,NULL);
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='system-builder'),'untracked filter not system');
INSERT INTO mlb_analysis_saved_filters VALUES('40000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001','team','{}');
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='system-builder'),'tracked saved system');
INSERT INTO chat_threads VALUES('50000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001');
INSERT INTO chat_messages VALUES('60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','assistant',' ');
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='wagerbot-partner'),'empty response does not count');
INSERT INTO chat_messages VALUES('60000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001','assistant','Completed research');
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='wagerbot-partner'),'persisted completed response counts');
SET ROLE authenticated;
SELECT record_achievement_activity('game_analysis'); SELECT record_achievement_activity('game_analysis');
SELECT test_assert((SELECT count(*) FROM user_achievement_awards WHERE achievement_id='game-analyst')=1,'idempotent activity');
SELECT test_assert(get_user_achievements()->'newly_unlocked_ids' ? 'game-analyst','pending celebration survives refresh');
SELECT acknowledge_achievement_celebrations(ARRAY['game-analyst']);
SELECT test_assert(NOT(get_user_achievements()->'newly_unlocked_ids' ? 'game-analyst'),'acknowledged celebration does not replay');
RESET ROLE;
SET ROLE service_role;
SELECT record_achievement_service_activity('10000000-0000-0000-0000-000000000001','mcp_tool_success');
RESET ROLE;
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='connected-researcher'),'trusted MCP event');
-- Eligible public ranking, deterministic tie order, and no private-agent rank awards.
UPDATE avatar_profiles SET is_public=true WHERE id='20000000-0000-0000-0000-000000000002';
UPDATE avatar_performance_cache SET total_picks=10,wins=6,losses=4,win_rate=.6,net_units=50,current_streak=2 WHERE avatar_id='20000000-0000-0000-0000-000000000002';
SELECT test_assert((SELECT count(*) FROM user_achievement_awards WHERE achievement_id IN ('top-100','top-10','number-one'))=3,'eligible observed leaderboard awards');
DELETE FROM avatar_profiles WHERE id='20000000-0000-0000-0000-000000000001';
SELECT test_assert(EXISTS(SELECT 1 FROM user_achievement_awards WHERE achievement_id='experience-10' AND credited_agent_id='20000000-0000-0000-0000-000000000001'),'deleted agent award retained');
SET ROLE authenticated;
SELECT test_assert((SELECT progress FROM jsonb_to_recordset(get_user_achievements()->'achievements') AS a(id text,progress numeric) WHERE id='experience-100')=1,'earned progress stays complete after deletion');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',false);
SET ROLE authenticated;
SELECT test_assert((SELECT count(*) FROM user_achievement_awards WHERE user_id='10000000-0000-0000-0000-000000000001')=0,'RLS isolates users');
SELECT test_assert(get_user_achievements()->'newly_unlocked_ids'='[]','existing history quietly backfilled');
SELECT test_assert((SELECT is_backfilled FROM user_achievement_awards WHERE achievement_id='first-agent'),'backfill flag persisted');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
SET ROLE authenticated;
DO $$ BEGIN BEGIN PERFORM get_user_achievements(); RAISE EXCEPTION 'Anonymous access allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; END $$;
RESET ROLE;
SELECT 'achievement SQL behavior checks passed' AS result;
